const chk=(ix,sk,lab)=>{if(ix.length<6)return;const v=ix.map(i=>-tx[i].amt),m=med(v),mad=med(v.map(x=>Math.abs(x-m)))||m*.1;ix.forEach(i=>{if(sk&&!sk(i))return;const z=.6745*(-tx[i].amt-m)/mad;if(z>3.5&&-tx[i].amt>1.5*m)o.set(i,'Far above your usual '+lab+' spend (typical '+fmt(m)+')')})};
