function lrnSum(){if(!LRN.n)return'I have not had enough history to check my forecasts yet. Add more transactions and I will start learning from my misses.';
const k=LRN.sk,w=LRN.w;return`I have checked ${LRN.n} forecast days against what really happened. ${LRN.miss} fell outside my 80% range (${pc(LRN.miss/LRN.n)}; about 20% is ideal). ${k>1.03?`You spend about ${pc(k-1)} more than my first estimate, so I now plan for that.`:k<.97?`You spend about ${pc(1-k)} less than my first estimate, so I now plan for that.`:'Your everyday spending matches my estimate well.'} ${w>1.05?`I widened my range by ${pc(w-1)} because your spending is less steady than I assumed.`:w<.95?`I narrowed my range by ${pc(1-w)} because you are steadier than I assumed.`:'My range width looks right.'}`}
