if(/^undo\b|^remove (the )?last/.test(t)){if(!BOTU)return'There is nothing of mine to undo.';const i=S.tx.indexOf(BOTU);if(i>=0)S.tx.splice(i,1);BOTU=null;load(S);return'Removed it. Balance is now '+fmt(B)+'.'}
let m=t.match(/^(?:remember|note)(?: that)?[: ]+(.+)/);if(m){NOTES.push(raw.trim().replace(/^(remember|note)( that)?[: ]+/i,'').slice(0,140));P('cpn',NOTES);return'Noted. I will keep that in mind.'}
