if(c&&n!=null&&(lim||/\b(set|change|make|update|put|keep)\b/.test(t))&&!/how much|what|spent|afford|add/.test(t)&&!up&&!dn){const out=[],av=catAvg();let w='';cats(c).forEach(k=>{const cur=curLimit(k);setL(k,n);out.push(`${k} limit is now ${fmt(n)} (was ${fmt(cur)})`);if(av[k]&&n<av[k]*.6)w+=` ${k} at ${fmt(n)} is well below your usual ${fmt(av[k])} a month, so it may be hard to keep.`});render();return out.join('; ')+'.'+w+risk()}
if(lim){const av=catAvg(),out=(c&&c!='all'?[c]:CAT4).filter(k=>av[k]||LIM[k]!=null).map(k=>`${k}: ${fmt(curLimit(k))}${LIM[k]!=null?'':' (suggested)'}, spent ${fmt(spent30(k))} in 30 days`);return out.length?out.join('\n'):'No spending data for limits yet.'}
if(/afford|can i (buy|spend|pay|get)|should i (buy|spend|pay|get)|is it (ok|safe)/.test(t)&&n!=null){const dm=t.match(/in\s+(\d+)\s*days?/),d=cl(dm?+dm[1]:7,1,60),s=sim(M,B,H,{extra:[{off:d,amt:-n}]}),dr=s.risk-F.risk;return`${dr>.15?'Risky.':dr>.05?'Manageable, but tight.':'Looks safe.'} Spending ${fmt(n)} in ${d} day${d>1?'s':''} moves shortage risk from ${pc(F.risk)} to ${pc(s.risk)}. Bad-case low point would be ${fmt(Math.min(...s.p10))}.`}
if(/\b(add|spent|spend|paid|pay|bought|received|got|earned|credited)\b/.test(t)&&n!=null&&!/how much|limit/.test(t)){const inc=/received|got|earned|credited|salary|income|paid me/.test(t),td=new Date();td.setHours(0,0,0,0);const d=Math.round((td-S.start)/864e5)+(/yesterday/.test(t)?-1:0);if(d<0)return'That date is before your first transaction.';
let ds=t.replace(/(₹|rs\.?|inr)?\s*\d[\d,]*(\.\d+)?\s*(k\b|thousand|lakh|lac)?/g,' ').replace(/\b(add|an?|the|spent|spend|paid|pay|bought|received|got|earned|credited|expense|income|on|for|from|to|today|yesterday|rupees|of|my|i)\b/g,' ').replace(/\s+/g,' ').trim();const mer={Food:'SWIGGY',Transport:'UBER',Shopping:'AMAZON'};
if(!inc&&c&&mer[c]&&!/swiggy|zomato|uber|\bola\b|amazon|myntra|flipkart/.test(ds))ds=(mer[c]+' '+ds.replace(/food|eating|dining|transport|travel|shopping/g,'')).trim();if(!ds)ds=inc?'Income':'Expense';
if(d>=S.N)S.N=d+1;const tx={d,desc:ds.toUpperCase(),amt:inc?n:-n};S.tx.push(tx);BOTU=tx;load(S);return`Added ${inc?'income':'expense'} of ${fmt(n)} (${ds}${inc?'':', counted as '+tx.cat}). Balance is now ${fmt(B)}. Say “undo” to remove it.`}
