function edC(c){EC=EC===c?null:c;EM='';render();if(EC)window.scrollTo(0,0)}
function edRows(){const r=[];S.tx.forEach((t,i)=>{if(t.d>S.N-31&&(EC=='IN'?t.amt>0:(t.amt<0&&t.cat==EC)))r.push(i)});return r}
function edBox(){if(EC==null)return'';const inc=EC=='IN',rows=edRows(),tot=rows.reduce((s,i)=>s+Math.abs(S.tx[i].amt),0);
return`<div class="cd" style="border-color:var(--ac)"><h2>Edit ${inc?'money received':EC.toLowerCase()} (last 30 days)</h2>${EM?`<p class="ok">${EM}</p>`:''}
<label>Total for this ${inc?'income':'category'} (₹) - changing it scales every item below</label><input id="etot" type="number" value="${Math.round(tot)}"><button class="btn" onclick="edTot()">Apply total</button>
${rows.map(i=>{const t=S.tx[i];return`<div style="border-top:1px solid var(--bd);margin-top:14px;padding-top:4px"><span class="mu">${dstr(t.d)}</span><label>Description</label><input id="en${i}" value="${t.desc.replace(/"/g,'&quot;')}"><label>Amount (₹)</label><input id="ea${i}" type="number" value="${Math.abs(t.amt)}">${inc?'':`<label>Category</label><select id="ec${i}">${CATS.map(c=>`<option${c==t.cat?' selected':''}>${c}</option>`).join('')}</select>`}<button class="btn" onclick="edSave(${i})">Save</button> <button class="btn s" onclick="edDel(${i})">Delete</button></div>`}).join('')||'<p class="mu">Nothing here in the last 30 days.</p>'}
<button class="btn s" onclick="edC(EC)">Close editor</button></div>`}
function edDone(m){const c=EC;load(S);EM=m;render()}
function edSave(i){const t=S.tx[i],a=Math.round(Math.abs(+$('#ea'+i).value));if(!a){EM='Enter an amount first.';render();return}t.amt=(t.amt<0?-1:1)*a;const d=$('#en'+i).value.trim();if(d)t.desc=d.toUpperCase();if(t.amt<0){t.c=$('#ec'+i).value}edDone('Saved. Balance is now '+fmt(B)+'.')}
function edDel(i){S.tx.splice(i,1);edDone('Deleted. Balance is now '+fmt(B)+'.')}
function edTot(){const n=Math.abs(+$('#etot').value),rows=edRows(),cur=rows.reduce((s,i)=>s+Math.abs(S.tx[i].amt),0);if(isNaN(n)||!rows.length){return}if(n===0){rows.sort((a,b)=>b-a).forEach(i=>S.tx.splice(i,1))}else{const f=n/cur;rows.forEach(i=>{const t=S.tx[i];t.amt=(t.amt<0?-1:1)*Math.max(1,Math.round(Math.abs(t.amt)*f))})}edDone('Total updated. Balance is now '+fmt(B)+'.')}
let MSG='';
